#pragma once
#include <juce_core/juce_core.h>
#include <vector>

// Factory library (resources/presets.json, generated by tools/gen_presets.py).
struct Preset
{
    juce::String name, original, synth, synthA, synthD, skinA, skinD, genre, decade, type, category, reference, notes;
    int year = 0;
    bool dance = false;          // Dance / House / Techno / Tech House family
    juce::NamedValueSet values;  // parameter id -> value (number or choice name)
};

class PresetLibrary
{
public:
    static const PresetLibrary& get();
    const std::vector<Preset>& all() const { return presets; }
    juce::StringArray decades, genres, categories;
private:
    PresetLibrary();
    std::vector<Preset> presets;
};
